using TownOfHost;using TownOfHost.Modules;using TownOfHost.Roles.Core;using TownOfHost.Roles.Crewmate;using TownOfHost.Roles.AddOns.Common;using System.Reflection;
class Program{
 static int passed;static void Check(bool value,string label="check"){if(!value)throw new Exception(label);}static void Test(string name,Action run){Reset();run();passed++;Console.WriteLine("PASS "+name);}
 static void Reset(){AmongUsClient.Instance=new();GameStates.IsMeeting=true;GameStates.ExiledAnimate=false;Marshall.ResetMeetingState();CustomRoleManager.AllActiveRoles.Clear();PlayerCatch.All.Clear();PlayerState.All.Clear();TownOfHost.Main.AllPlayerNames.Clear();Utils.Sent.Clear();HudManager.Instance=new();SelfVoteManager.Init();Amnesia.Disabled=false;TownOfHost.Roles.Madmate.MadAvenger.Skill=false;TownOfHost.Roles.Impostor.Assassin.NowUse=false;TownOfHost.Main.NormalOptions.NumEmergencyMeetings=1;MeetingVoteManager.Instance=new();var info=Marshall.RoleInfo;Options.VoteMode.Value=false;Options.WhenTie.Value=0;MeetingHudPatch.Queued.Clear();OptionItem.Items.Clear();OptionItem.Items[info.ConfigId]=info.RoleOption;info.Setup();for(byte i=0;i<8;i++){PlayerCatch.All[i]=new(){PlayerId=i,ClientId=100+i,Data=new(){PlayerName="Fixture"+i}};PlayerState.All[i]=new();TownOfHost.Main.AllPlayerNames[i]="Fixture"+i;}PlayerControl.LocalPlayer=PlayerCatch.All[7];}
 static void Set(string key,int value){var option=(IntegerOptionItem)OptionItem.Items.Values.Single(o=>o.Name==key);option.SetValue(option.Rule.GetNearestIndex(value),false);}
 static Marshall Role(byte id=0){var role=new Marshall(PlayerCatch.All[id]);CustomRoleManager.AllActiveRoles[id]=role;role.Add();return role;}
 static void Begin(params Marshall[] roles){Marshall.PrepareMeeting();Marshall.OpenMeeting();foreach(var role in roles)role.OnStartMeeting();Utils.Sent.Clear();HudManager.Instance.Chat.Messages.Clear();}
 static bool Vote(Marshall role,byte voter,byte target)=>role.CheckVoteAsVoter(target,PlayerCatch.All[voter]);
 static void Apply(Marshall role,byte owner,byte target){Check(!Vote(role,owner,owner));Check(!Vote(role,owner,target));}
 static Dictionary<byte,int> Counts(params (byte,int)[] values)=>values.ToDictionary(x=>x.Item1,x=>x.Item2);
 static void Main(){
 Test("three settings have unique IDs defaults and bounds",()=>{Check(Marshall.RoleInfo.ConfigId==40200&&Marshall.RoleInfo.From==From.TownOfHost_Shell);Check(OptionItem.Items.Count==4);foreach(var id in new[]{40210,40211,40212})Check(OptionItem.Items.ContainsKey(id));Check(OptionItem.Items[40210].GetInt()==2&&OptionItem.Items[40211].GetInt()==5&&OptionItem.Items[40212].GetInt()==1);var a=(IntegerOptionItem)OptionItem.Items[40210];Check(a.Rule.MinValue==0&&a.Rule.MaxValue==99&&a.Rule.Step==1);});
 Test("zero total is disabled and separate minus-one total is infinity",()=>{Set("MarshallTotalUses",0);Check(OptionItem.Items[40211].GetString()=="0");Set("MarshallTotalUses",-1);Check(OptionItem.Items[40211].GetString()=="∞");});
 Test("per-meeting zero follows existing infinity notation",()=>{Set("MarshallMeetingUses",0);Check(OptionItem.Items[40212].GetString()=="∞");});
 Test("extra emergency count adds two and marks settings dirty",()=>{Role();Check(PlayerState.All[0].NumberOfRemainingButtons==3&&PlayerCatch.All[0].Dirty);});
 Test("global zero-emergency prohibition remains zero",()=>{TownOfHost.Main.NormalOptions.NumEmergencyMeetings=0;PlayerState.All[0].NumberOfRemainingButtons=0;Role();Check(PlayerState.All[0].NumberOfRemainingButtons==0);});
 Test("maximum additional emergency count is representable",()=>{Set("MarshallAdditionalButtons",99);Role();Check(PlayerState.All[0].NumberOfRemainingButtons==100);});
 Test("non-host cannot grant emergency counts",()=>{AmongUsClient.Instance.AmHost=false;Role();Check(PlayerState.All[0].NumberOfRemainingButtons==1);});
 Test("tie selects a top player",()=>Check(MarshallVoteRules.Preferred(Counts((1,3),(2,3)),new byte[]{1})==1));
 Test("skip may win a top tie",()=>Check(MarshallVoteRules.Preferred(Counts((1,3),(253,3)),new byte[]{253})==253));
 Test("three-way tie can prefer a top player",()=>Check(MarshallVoteRules.Preferred(Counts((1,3),(2,3),(3,3)),new byte[]{2})==2));
 Test("non-tie is never overridden",()=>Check(MarshallVoteRules.Preferred(Counts((1,4),(2,3)),new byte[]{2})==254));
 Test("outside-top preference leaves old path",()=>Check(MarshallVoteRules.Preferred(Counts((1,4),(2,4),(3,2)),new byte[]{3})==254));
 Test("conflicting Marshalls do not impose a majority",()=>Check(MarshallVoteRules.Preferred(Counts((1,3),(2,3)),new byte[]{1,1,2})==254));
 Test("agreeing Marshalls select their common top target",()=>Check(MarshallVoteRules.Preferred(Counts((1,3),(2,3)),new byte[]{1,1})==1));
 Test("no ballots or all-zero count cannot break ties",()=>{Check(MarshallVoteRules.Preferred(Counts((1,3),(2,3)),Array.Empty<byte>())==254);Check(MarshallVoteRules.Preferred(Counts((1,0),(2,0)),new byte[]{1})==254);});
 Test("maximum candidates and ballot order do not change rules",()=>{foreach(var order in new[]{new byte[]{1,2},new byte[]{2,1}})Check(MarshallVoteRules.Preferred(Counts((1,9),(2,9),(253,9)),order)==254);});
 Test("vote penalty lowers single and multiple votes but never negative",()=>{Check(MarshallVoteRules.Adjust(1,true)==0);Check(MarshallVoteRules.Adjust(5,true)==4);Check(MarshallVoteRules.Adjust(0,true)==0);Check(MarshallVoteRules.Adjust(int.MinValue,true)==0);Check(MarshallVoteRules.Adjust(5,false)==5);});
 Test("self then target consumes one use without casting either vote",()=>{var role=Role();Begin(role);Apply(role,0,1);Check(Marshall.AdjustPower(1,1)==0);Check(role.GetProgressText().Contains("(4/0)"));});
 Test("normal vote remains a normal vote",()=>{var role=Role();Begin(role);Check(Vote(role,0,1));Check(Marshall.AdjustPower(1,1)==1);});
 Test("self twice cancels without spending",()=>{var role=Role();Begin(role);Check(!Vote(role,0,0));Check(!Vote(role,0,0));Check(Vote(role,0,1));Check(role.GetProgressText().Contains("(5/1)"));});
 Test("skip cancels ability selection rather than becoming a player",()=>{var role=Role();Begin(role);Vote(role,0,0);Check(!Vote(role,0,253));Check(!Marshall.Meeting.Suppressed.Contains(253));Check(Vote(role,0,253));});
 Test("total zero cannot use martial law",()=>{Set("MarshallTotalUses",0);var role=Role();Begin(role);Check(Vote(role,0,0));Check(Marshall.Meeting.Suppressed.Count==0);});
 Test("default meeting cap prevents a second ability",()=>{var role=Role();Begin(role);Apply(role,0,1);Check(Vote(role,0,0));Check(Vote(role,0,2));Check(Marshall.Meeting.Suppressed.Count==1);});
 Test("unlimited meeting cap allows distinct targets",()=>{Set("MarshallMeetingUses",0);var role=Role();Begin(role);Apply(role,0,1);Apply(role,0,2);Check(role.GetProgressText().Contains("(3/∞)"));});
 Test("unlimited total preserves zero disabled semantics",()=>{Set("MarshallTotalUses",-1);Set("MarshallMeetingUses",0);var role=Role();Begin(role);for(byte i=1;i<7;i++)Apply(role,0,i);Check(role.GetProgressText().Contains("(∞/∞)"));});
 Test("next meeting resets meeting quota but retains total quota",()=>{var role=Role();Begin(role);Apply(role,0,1);Marshall.CloseMeeting();Begin(role);Check(role.GetProgressText().Contains("(4/1)"));Apply(role,0,1);Check(role.GetProgressText().Contains("(3/0)"));});
 Test("total limit survives repeated meetings",()=>{Set("MarshallTotalUses",2);var role=Role();for(int i=0;i<2;i++){Begin(role);Apply(role,0,1);Marshall.CloseMeeting();}Begin(role);Check(Vote(role,0,0));Check(role.GetProgressText().Contains("(0/1)"));});
 Test("same target cannot be charged twice by one Marshal",()=>{Set("MarshallMeetingUses",0);var role=Role();Begin(role);Apply(role,0,1);Vote(role,0,0);Check(!Vote(role,0,1));Check(role.GetProgressText().Contains("(4/∞)"));});
 Test("same target is shared across Marshalls without spending loser quota",()=>{var a=Role(0);var b=Role(2);Begin(a,b);Apply(a,0,1);Apply(b,2,1);Check(b.GetProgressText().Contains("(5/1)"));Check(Marshall.AdjustPower(1,2)==1);});
 Test("dead target cannot consume a use",()=>{var role=Role();Begin(role);PlayerCatch.All[1].Data.IsDead=true;Apply(role,0,1);Check(role.GetProgressText().Contains("(5/1)"));});
 Test("disconnected target cannot consume a use",()=>{var role=Role();Begin(role);PlayerCatch.All[1].Data.Disconnected=true;Apply(role,0,1);Check(role.GetProgressText().Contains("(5/1)"));});
 Test("missing target cannot consume a use",()=>{var role=Role();Begin(role);Apply(role,0,50);Check(role.GetProgressText().Contains("(5/1)"));});
 Test("known zero-power ballot cannot consume a use",()=>{var role=Role();Begin(role);MeetingVoteManager.Instance.AllVotes[1]=new(){Voter=1,VotedFor=2,NumVotes=0};Apply(role,0,1);Check(role.GetProgressText().Contains("(5/1)"));});
 Test("non-host selection cannot mutate suppression",()=>{var role=Role();Begin(role);AmongUsClient.Instance.AmHost=false;Check(Vote(role,0,0)&&Vote(role,0,1));Check(Marshall.Meeting.Suppressed.Count==0);});
 Test("dead Marshall cannot act",()=>{var role=Role();Begin(role);PlayerCatch.All[0].Data.IsDead=true;Check(Vote(role,0,0)&&Vote(role,0,1));Check(Marshall.Meeting.Suppressed.Count==0);});
 Test("exile animation rejects last-second ability",()=>{var role=Role();Begin(role);GameStates.ExiledAnimate=true;Check(Vote(role,0,0));Check(Marshall.Meeting.Suppressed.Count==0);});
 Test("ordinary self-vote ability gates are preserved",()=>{var role=Role();Begin(role);TownOfHost.Roles.Impostor.Assassin.NowUse=true;Check(Vote(role,0,0));Check(Marshall.Meeting.Suppressed.Count==0);});
 Test("host ignores counter RPC from a remote client",()=>{var role=Role();Begin(role);role.ReceiveRPC(new Hazel.MessageReader(999,999));Check(role.GetProgressText().Contains("(5/1)"));});
 Test("non-host reads display counters without changing host ledger",()=>{var role=Role();Begin(role);AmongUsClient.Instance.AmHost=false;role.ReceiveRPC(new Hazel.MessageReader(2,1));Check(role.GetProgressText().Contains("(3/0)"));Check(Marshall.Meeting.Suppressed.Count==0);});
 Test("live adapter includes only intentional positive living Marshal ballots",()=>{var role=Role();Begin(role);MeetingVoteManager.Instance.AllVotes[0]=new(){Voter=0,VotedFor=1,NumVotes=1};Check(Marshall.Preferred(Counts((1,3),(2,3)))==1);MeetingVoteManager.Instance.AllVotes[0].Intentional=false;Check(Marshall.Preferred(Counts((1,3),(2,3)))==254);});
 Test("a zero-effective Marshal ballot cannot break a tie",()=>{var role=Role();Begin(role);MeetingVoteManager.Instance.AllVotes[0]=new(){Voter=0,VotedFor=1,NumVotes=1};Marshall.Meeting.Suppressed.Add(0);Check(Marshall.Preferred(Counts((1,3),(2,3)))==254);});
 Test("dead Marshal and dead preference target cannot break tie",()=>{var role=Role();Begin(role);MeetingVoteManager.Instance.AllVotes[0]=new(){Voter=0,VotedFor=1};PlayerCatch.All[0].Data.IsDead=true;Check(Marshall.Preferred(Counts((1,3),(2,3)))==254);PlayerCatch.All[0].Data.IsDead=false;PlayerCatch.All[1].Data.IsDead=true;Check(Marshall.Preferred(Counts((1,3),(2,3)))==254);});
 Test("meeting death is private to living Marshall",()=>{var role=Role();Begin(role);PlayerCatch.All[1].Data.IsDead=true;Marshall.ReportMeetingDeath(1);Check(Utils.Sent.Count==1&&Utils.Sent[0].recipient==0);});
 Test("death report reaches host locally without a broadcast",()=>{PlayerControl.LocalPlayer=PlayerCatch.All[0];var role=Role();Begin(role);string name=PlayerCatch.All[0].Data.PlayerName;PlayerCatch.All[1].Data.IsDead=true;Marshall.ReportMeetingDeath(1);Check(Utils.Sent.Count==0&&HudManager.Instance.Chat.Messages.Count==1);Check(PlayerCatch.All[0].Data.PlayerName==name);});
 Test("invalid private ClientId never falls back to all players",()=>{var role=Role();Begin(role);PlayerCatch.All[0].ClientId=-1;Marshall.ReportMeetingDeath(1);Check(Utils.Sent.Count==0&&HudManager.Instance.Chat.Messages.Count==0);});
 Test("pre-meeting dead players never produce a report",()=>{var role=Role();PlayerCatch.All[1].Data.IsDead=true;Begin(role);Marshall.ReportMeetingDeath(1);Check(Utils.Sent.Count==0);});
 Test("report-preparation delayed kill is excluded after HUD opens",()=>{var role=Role();Marshall.PrepareMeeting();Marshall.RecordConfirmedKill(1);Marshall.OpenMeeting();role.OnStartMeeting();Utils.Sent.Clear();Marshall.ReportMeetingDeath(1);Check(Utils.Sent.Count==0);});
 Test("queued pre-meeting RPC death is excluded despite meeting-time display",()=>{var role=Role();GameStates.IsMeeting=false;Marshall.RecordConfirmedKill(1);GameStates.IsMeeting=true;Begin(role);Marshall.ReportMeetingDeath(1);Check(Utils.Sent.Count==0);});
 Test("confirmed meeting kill reports exactly once",()=>{var role=Role();Begin(role);Marshall.RecordConfirmedKill(1);Marshall.ReportMeetingDeath(1);Marshall.ReportMeetingDeath(1);Check(Utils.Sent.Count==1);});
 Test("missing death role and reason degrade to unknown",()=>{var role=Role();Begin(role);PlayerState.All.Remove(1);PlayerCatch.All.Remove(1);Marshall.ReportMeetingDeath(1);Check(Utils.Sent.Count==1&&Utils.Sent[0].body.Contains("Unknown"));});
 Test("meeting-time death is hidden from dead Marshall and other crew",()=>{var role=Role();Begin(role);PlayerCatch.All[0].Data.IsDead=true;Marshall.ReportMeetingDeath(1);Check(Utils.Sent.Count==0);});
 Test("non-host cannot produce death notices",()=>{var role=Role();Begin(role);AmongUsClient.Instance.AmHost=false;Marshall.ReportMeetingDeath(1);Check(Utils.Sent.Count==0);});
 Test("closed meeting cannot leak post-exile information",()=>{var role=Role();Begin(role);Marshall.CloseMeeting();Marshall.ReportMeetingDeath(1);Check(Utils.Sent.Count==0&&Marshall.AdjustPower(1,1)==1);});
 Test("meeting generation excludes unresolved older kills",()=>{var l=new MarshallMeetingLedger();l.Prepare();l.Begin(new byte[]{1});l.QueueKill(1,true);l.Close();l.Prepare();l.Begin(new byte[]{1});Check(!l.Death(1,true));});
 Test("a new meeting kill replaces stale cause without false exclusion",()=>{var l=new MarshallMeetingLedger();l.QueueKill(1,false);l.Prepare();l.Begin(new byte[]{1});l.QueueKill(1,true);Check(l.Death(1,true));});
 Test("reset removes all temporary votes and causes",()=>{var l=new MarshallMeetingLedger();l.Prepare();l.Begin(new byte[]{1});l.Suppressed.Add(1);l.QueueKill(1,true);l.Reset();Check(!l.Open&&l.Generation==0&&l.Suppressed.Count==0);});
 Test("use-rule failures never spend quota",()=>{var u=new MarshallUsage();foreach(var args in new[]{(false,false,false),(true,true,false),(true,false,true)})Check(!u.TrySpend(5,1,args.Item1,args.Item2,args.Item3));Check(u.TotalUsed==0&&u.MeetingUsed==0);});
 Test("repeated Add does not grant more emergency buttons",()=>{var r=Role();r.Add();Check(PlayerState.All[0].NumberOfRemainingButtons==3);});
 Test("private local chat failure never interrupts death state",()=>{var r=Role();Begin(r);PlayerControl.LocalPlayer=PlayerCatch.All[0];HudManager.Instance.Chat.Throw=true;Marshall.ReportMeetingDeath(1);Check(Utils.Sent.Count==0);});

 Test("actual constructor applies Marshall before ordinary Tiebreaker",()=>{var r=Role();Begin(r);MeetingVoteManager.Instance.AllVotes[0]=new(){Voter=0,VotedFor=1};var result=new MeetingVoteManager.VoteResult(Counts((1,3),(2,3)),Counts((1,0),(2,1)));Check(!result.IsTie&&result.Exiled.PlayerId==1);});
 Test("actual constructor resolves Skip without looking up a player",()=>{var r=Role();Begin(r);MeetingVoteManager.Instance.AllVotes[0]=new(){Voter=0,VotedFor=253};var result=new MeetingVoteManager.VoteResult(Counts((1,3),(253,3)),Counts((1,0),(253,0)));Check(!result.IsTie&&result.Exiled==null);});
 Test("actual constructor resolves three-way tie",()=>{var r=Role();Begin(r);MeetingVoteManager.Instance.AllVotes[0]=new(){Voter=0,VotedFor=2};var result=new MeetingVoteManager.VoteResult(Counts((1,4),(2,4),(3,4)),Counts((1,0),(2,0),(3,0)));Check(result.Exiled.PlayerId==2&&!result.IsTie);});
 Test("actual constructor never changes a non-tie",()=>{var r=Role();Begin(r);MeetingVoteManager.Instance.AllVotes[0]=new(){Voter=0,VotedFor=2};var result=new MeetingVoteManager.VoteResult(Counts((1,4),(2,3)),Counts((1,0),(2,1)));Check(result.Exiled.PlayerId==1);});
 Test("actual constructor preserves old Tiebreaker on Marshal conflict",()=>{var a=Role();var b=Role(3);Begin(a,b);MeetingVoteManager.Instance.AllVotes[0]=new(){Voter=0,VotedFor=1};MeetingVoteManager.Instance.AllVotes[3]=new(){Voter=3,VotedFor=2};var result=new MeetingVoteManager.VoteResult(Counts((1,3),(2,3)),Counts((1,0),(2,1)));Check(result.Exiled.PlayerId==2&&!result.IsTie);});
 Test("actual constructor uses corrected final vote counts",()=>{var r=Role();Begin(r);Marshall.Meeting.Suppressed.Add(1);MeetingVoteManager.Instance.AllVotes[0]=new(){Voter=0,VotedFor=1};var result=new MeetingVoteManager.VoteResult(Counts((1,Marshall.AdjustPower(1,4)),(2,3)),Counts((1,0),(2,0)));Check(result.Exiled.PlayerId==1);});
 Test("actual constructor preserves Judge override and nonce",()=>{var r=Role();Begin(r);MeetingVoteManager.Instance.AllVotes[0]=new(){Voter=0,VotedFor=1};var result=new MeetingVoteManager.VoteResult(Counts((1,3),(2,3)),Counts((1,0),(2,0)),false,2,7);Check(result.Exiled.PlayerId==2&&result.OverrideExiled==2&&result.OverruleNonce==7);});
 Test("actual constructor excludes Marshall from forced-exile path",()=>{var r=Role();Begin(r);MeetingVoteManager.Instance.AllVotes[0]=new(){Voter=0,VotedFor=1};var result=new MeetingVoteManager.VoteResult(Counts((1,3),(2,3)),Counts((1,0),(2,1)),true);Check(result.Exiled.PlayerId==2);});
 Test("actual constructor retains ordinary all-tie mode when no preference",()=>{Options.VoteMode.Value=true;Options.WhenTie.Value=(int)Options.TieMode.All;var result=new MeetingVoteManager.VoteResult(Counts((1,3),(2,3)),Counts((1,0),(2,0)));Check(result.IsTie&&result.Exiled==null&&MeetingHudPatch.Queued.SequenceEqual(new byte[]{1,2}));});
 Test("actual constructor does not all-exile a Marshal skip preference",()=>{Options.VoteMode.Value=true;Options.WhenTie.Value=(int)Options.TieMode.All;var r=Role();Begin(r);MeetingVoteManager.Instance.AllVotes[0]=new(){Voter=0,VotedFor=253};var result=new MeetingVoteManager.VoteResult(Counts((1,3),(253,3)),Counts((1,0),(253,0)));Check(!result.IsTie&&result.Exiled==null&&MeetingHudPatch.Queued.Count==0);});
 Test("actual constructor ignores dead Marshal preference",()=>{var r=Role();Begin(r);MeetingVoteManager.Instance.AllVotes[0]=new(){Voter=0,VotedFor=1};PlayerCatch.All[0].Data.IsDead=true;var result=new MeetingVoteManager.VoteResult(Counts((1,3),(2,3)),Counts((1,0),(2,0)));Check(result.IsTie&&result.Exiled==null);});
 Test("actual constructor excludes automatic no-vote conversion",()=>{var r=Role();Begin(r);MeetingVoteManager.Instance.AllVotes[0]=new(){Voter=0,VotedFor=1,Intentional=false};var result=new MeetingVoteManager.VoteResult(Counts((1,3),(2,3)),Counts((1,0),(2,0)));Check(result.IsTie);});
 Test("disposing last Marshal clears meeting and penalties",()=>{var r=Role();Begin(r);Apply(r,0,1);r.OnDestroy();Check(!Marshall.Meeting.Open&&Marshall.AdjustPower(1,1)==1);});
 Test("one Marshal disposal preserves another active Marshal meeting",()=>{var a=Role();var b=Role(2);Begin(a,b);a.OnDestroy();Check(Marshall.Meeting.Open);b.OnDestroy();Check(!Marshall.Meeting.Open);});
 Test("Marshal death cancels selection but keeps established law until meeting end",()=>{var r=Role();Begin(r);Apply(r,0,1);r.OnDead(PlayerCatch.All[0]);Check(Marshall.AdjustPower(1,1)==0);Marshall.CloseMeeting();Check(Marshall.AdjustPower(1,1)==1);});
 Console.WriteLine($"RESULT {passed} passed, 0 failed (actual Marshall, integer option rules and SelfVoteManager; Unity/chat/RPC substitutes)");
 }
}
